# ============================================================
# SAFEVISION AI — BROWSER INCIDENT API
# ============================================================
#
# Handles normal browser incidents and permanent demo incidents.
#
# Demo incidents #1-#5 are versioned so evidence generated by
# an older/raw-image seeder is automatically replaced by the
# current browser ONNX / MediaPipe inference flow.
#
# ============================================================

import base64
import binascii

from datetime import (
    datetime,
    timedelta,
    timezone,
)

from fastapi import (
    APIRouter,
    Depends,
    HTTPException,
)

from pydantic import (
    BaseModel,
    Field,
)

from sqlalchemy import (
    delete,
    func,
    select,
    text,
)

from sqlalchemy.orm import Session

from app.db.models import (
    Camera,
    Incident,
    IncidentEvidence,
)

from app.db.session import (
    get_db,
)

from app.schemas.incidents import (
    IncidentCreate,
    IncidentRead,
)

from app.services.evidence import (
    save_evidence_bytes_to_db,
)

from app.services.incident_service import (
    create_incident_if_new,
)


# ============================================================
# INCIDENT CONFIGURATION
# ============================================================

SEVERITY_BY_PPE = {
    "hardhat": "high",
    "vest": "high",
    "mask": "medium",
    "gloves": "medium",
}


DEMO_IDS = [
    1,
    2,
    3,
    4,
    5,
]


DEMO_MINUTE_OFFSETS = {
    1: 4,
    2: 11,
    3: 19,
    4: 28,
    5: 37,
}


DEMO_INITIAL_STATUSES = {
    1: "open",
    2: "reviewing",
    3: "resolved",
    4: "open",
    5: "resolved",
}


# Increment this whenever the demo-generation logic changes.
#
# Old demo rows will automatically become "not ready" and the
# browser will rerun inference on the five project images.
DEMO_SEED_VERSION = (
    "safevision-browser-inference-v3"
)


DEMO_SEED_MARKER = (
    f"[demo_seed_version={DEMO_SEED_VERSION}]"
)


MAX_EVIDENCE_BYTES = (
    2_500_000
)


router = APIRouter(
    prefix="/browser-incidents",
    tags=[
        "browser-incidents"
    ],
)


# ============================================================
# SCHEMAS
# ============================================================

class BrowserIncidentCreate(
    BaseModel
):
    camera_id: int = Field(
        ge=1,
    )

    track_id: int = Field(
        ge=1,
    )

    missing_ppe: str

    confidence: float = Field(
        ge=0.0,
        le=1.0,
    )

    evidence_image: (
        str | None
    ) = None


class BrowserIncidentResponse(
    BaseModel
):
    created: bool

    incident: IncidentRead

    evidence_saved: bool


class DemoIncidentCreate(
    BaseModel
):
    incident_id: int = Field(
        ge=1,
        le=5,
    )

    camera_id: int = Field(
        default=1,
        ge=1,
    )

    track_id: int = Field(
        ge=1,
    )

    missing_ppe: str

    confidence: float | None = Field(
        default=None,
        ge=0.0,
        le=1.0,
    )

    inferred: bool = False

    evidence_image: str


class DemoIncidentStatusResponse(
    BaseModel
):
    ready: bool

    demo_ids: list[int]


# ============================================================
# PPE NORMALIZATION
# ============================================================

def normalize_missing_ppe(
    value: str,
) -> str:
    normalized = (
        value
        .strip()
        .lower()
        .replace(
            "-",
            "_",
        )
        .replace(
            " ",
            "_",
        )
    )

    aliases = {
        "hardhat":
            "hardhat",

        "helmet":
            "hardhat",

        "no_hardhat":
            "hardhat",

        "missing_hardhat":
            "hardhat",

        "vest":
            "vest",

        "safety_vest":
            "vest",

        "no_vest":
            "vest",

        "no_safety_vest":
            "vest",

        "missing_vest":
            "vest",

        "mask":
            "mask",

        "no_mask":
            "mask",

        "missing_mask":
            "mask",

        "gloves":
            "gloves",

        "glove":
            "gloves",

        "no_gloves":
            "gloves",

        "no_glove":
            "gloves",

        "missing_gloves":
            "gloves",

        "missing_glove":
            "gloves",
    }

    result = aliases.get(
        normalized,
    )

    if result is None:
        raise HTTPException(
            status_code=422,
            detail=(
                "Expected hardhat, "
                "vest, mask, or gloves."
            ),
        )

    return result


# ============================================================
# EVIDENCE DECODING
# ============================================================

def decode_evidence_image(
    data_url: str,
) -> tuple[bytes, str]:

    if not data_url.startswith(
        "data:"
    ):
        raise HTTPException(
            status_code=422,
            detail=(
                "Evidence image must "
                "be a browser data URL."
            ),
        )

    try:
        header, encoded = (
            data_url.split(
                ",",
                1,
            )
        )

    except ValueError:
        raise HTTPException(
            status_code=422,
            detail=(
                "Invalid evidence image."
            ),
        )

    if ";base64" not in header:
        raise HTTPException(
            status_code=422,
            detail=(
                "Evidence image must "
                "use base64 encoding."
            ),
        )

    mime_type = (
        header
        .removeprefix(
            "data:"
        )
        .split(
            ";",
            1,
        )[0]
        .lower()
    )

    allowed_mime_types = {
        "image/jpeg",
        "image/png",
    }

    if (
        mime_type
        not in allowed_mime_types
    ):
        raise HTTPException(
            status_code=422,
            detail=(
                "Evidence must be "
                "JPEG or PNG."
            ),
        )

    try:
        image_bytes = (
            base64.b64decode(
                encoded,
                validate=True,
            )
        )

    except (
        binascii.Error,
        ValueError,
    ):
        raise HTTPException(
            status_code=422,
            detail=(
                "Evidence image contains "
                "invalid base64."
            ),
        )

    if not image_bytes:
        raise HTTPException(
            status_code=422,
            detail=(
                "Evidence image is empty."
            ),
        )

    if (
        len(
            image_bytes
        )
        > MAX_EVIDENCE_BYTES
    ):
        raise HTTPException(
            status_code=413,
            detail=(
                "Evidence image "
                "is too large."
            ),
        )

    return (
        image_bytes,
        mime_type,
    )


# ============================================================
# DEMO HELPERS
# ============================================================

def demo_detected_at(
    incident_id: int,
) -> datetime:

    return (
        datetime.now(
            timezone.utc
        )
        - timedelta(
            minutes=(
                DEMO_MINUTE_OFFSETS[
                    incident_id
                ]
            )
        )
    )


def demo_resolved_at(
    detected_at: datetime,
    status: str,
) -> datetime | None:

    if status != "resolved":
        return None

    return (
        detected_at
        + timedelta(
            minutes=6
        )
    )


def current_demo_incidents(
    db: Session,
) -> list[Incident]:

    return list(
        db.scalars(
            select(
                Incident
            )
            .where(
                Incident.id.in_(
                    DEMO_IDS
                )
            )
            .order_by(
                Incident.id.asc()
            )
        ).all()
    )


def incident_has_evidence(
    db: Session,
    incident_id: int,
) -> bool:

    evidence_id = db.scalar(
        select(
            IncidentEvidence.id
        )
        .where(
            IncidentEvidence.incident_id
            == incident_id
        )
        .limit(
            1
        )
    )

    return (
        evidence_id
        is not None
    )


def demo_is_current(
    db: Session,
    incident: Incident,
) -> bool:

    if (
        incident.id
        not in DEMO_IDS
    ):
        return False

    if not incident.is_demo:
        return False

    if not incident_has_evidence(
        db,
        incident.id,
    ):
        return False

    notes = (
        incident.notes
        or ""
    )

    # This is the key fix.
    #
    # Old Python/raw-image seeded incidents do not have this
    # marker, so the browser is forced to regenerate them.
    if (
        DEMO_SEED_MARKER
        not in notes
    ):
        return False

    # Trained ONNX detections must have genuine confidence.
    #
    # Gloves are allowed to be null because NO-Gloves is
    # inferred instead of being a trained model class.
    if (
        incident.violation_type
        != "gloves"
        and incident.confidence
        is None
    ):
        return False

    return True


def current_demo_ids(
    db: Session,
) -> list[int]:

    incidents = (
        current_demo_incidents(
            db
        )
    )

    result = []

    for incident in incidents:

        if demo_is_current(
            db,
            incident,
        ):
            result.append(
                incident.id
            )

    return result


def sync_incident_sequence(
    db: Session,
) -> None:

    max_id = db.scalar(
        select(
            func.max(
                Incident.id
            )
        )
    )

    sequence_value = max(
        int(
            max_id
            or 0
        ),
        5,
    )

    db.execute(
        text(
            """
            SELECT setval(
                pg_get_serial_sequence(
                    'incidents',
                    'id'
                ),
                :sequence_value,
                true
            )
            """
        ),
        {
            "sequence_value":
                sequence_value,
        },
    )


# ============================================================
# DEMO STATUS
# ============================================================

@router.get(
    "/demo/status",
    response_model=(
        DemoIncidentStatusResponse
    ),
)
def get_demo_status(
    db: Session = Depends(
        get_db
    ),
):

    demo_ids = (
        current_demo_ids(
            db
        )
    )

    return (
        DemoIncidentStatusResponse(
            ready=(
                demo_ids
                == DEMO_IDS
            ),

            demo_ids=(
                demo_ids
            ),
        )
    )


# ============================================================
# CREATE / REPLACE DEMO INCIDENT
# ============================================================

@router.post(
    "/demo",
    response_model=(
        BrowserIncidentResponse
    ),
)
def create_or_replace_demo_incident(
    payload: DemoIncidentCreate,

    db: Session = Depends(
        get_db
    ),
):

    if (
        payload.incident_id
        not in DEMO_IDS
    ):
        raise HTTPException(
            status_code=422,
            detail=(
                "Demo incident ID "
                "must be 1 through 5."
            ),
        )

    camera = db.get(
        Camera,
        payload.camera_id,
    )

    if camera is None:
        raise HTTPException(
            status_code=400,
            detail=(
                f"Camera "
                f"{payload.camera_id} "
                "does not exist."
            ),
        )

    missing_ppe = (
        normalize_missing_ppe(
            payload.missing_ppe
        )
    )

    # ========================================================
    # CONFIDENCE RULES
    # ========================================================

    if payload.inferred:

        if (
            missing_ppe
            != "gloves"
        ):
            raise HTTPException(
                status_code=422,
                detail=(
                    "Only gloves may use "
                    "inferred demo mode."
                ),
            )

        # NO-Gloves is inferred.
        #
        # Do not pretend the heuristic score is a trained
        # model confidence.
        incident_confidence = None

    else:

        if (
            payload.confidence
            is None
        ):
            raise HTTPException(
                status_code=422,
                detail=(
                    "A trained demo "
                    "violation requires "
                    "a confidence value."
                ),
            )

        incident_confidence = (
            payload.confidence
        )


    # ========================================================
    # DECODE NEW EVIDENCE FIRST
    # ========================================================

    image_bytes, mime_type = (
        decode_evidence_image(
            payload.evidence_image
        )
    )


    # ========================================================
    # REMOVE OLD DEMO DATA AT THIS FIXED ID
    # ========================================================

    db.execute(
        delete(
            IncidentEvidence
        ).where(
            IncidentEvidence.incident_id
            == payload.incident_id
        )
    )

    existing = db.get(
        Incident,
        payload.incident_id,
    )

    if existing is not None:

        db.delete(
            existing
        )

        db.flush()


    # ========================================================
    # CREATE NEW CURRENT DEMO RECORD
    # ========================================================

    detected_at = (
        demo_detected_at(
            payload.incident_id
        )
    )

    status = (
        DEMO_INITIAL_STATUSES[
            payload.incident_id
        ]
    )

    inference_description = (
        "MediaPipe NO-Gloves inference"
        if payload.inferred
        else
        "browser ONNX inference"
    )

    notes = (
        f"{DEMO_SEED_MARKER} "
        "Permanent SafeVision portfolio demo incident "
        "generated from a project demo image using "
        f"{inference_description}."
    )

    incident = Incident(
        id=(
            payload.incident_id
        ),

        camera_id=(
            payload.camera_id
        ),

        track_id=(
            payload.track_id
        ),

        violation_type=(
            missing_ppe
        ),

        missing_ppe=[
            missing_ppe
        ],

        severity=(
            SEVERITY_BY_PPE[
                missing_ppe
            ]
        ),

        confidence=(
            incident_confidence
        ),

        detected_at=(
            detected_at
        ),

        status=(
            status
        ),

        resolved_at=(
            demo_resolved_at(
                detected_at,
                status,
            )
        ),

        notes=(
            notes
        ),

        evidence_path=None,

        is_demo=True,
    )

    db.add(
        incident
    )

    db.flush()


    # ========================================================
    # SAVE ANNOTATED BROWSER EVIDENCE
    # ========================================================

    save_evidence_bytes_to_db(
        db=db,

        incident_id=(
            incident.id
        ),

        image_bytes=(
            image_bytes
        ),

        mime_type=(
            mime_type
        ),

        keep_latest=100,
    )


    sync_incident_sequence(
        db
    )

    db.commit()

    db.refresh(
        incident
    )

    return (
        BrowserIncidentResponse(
            created=True,

            incident=(
                IncidentRead
                .model_validate(
                    incident
                )
            ),

            evidence_saved=True,
        )
    )


# ============================================================
# REFRESH DEMO TIMESTAMPS
# ============================================================

@router.post(
    "/demo/refresh",
    response_model=(
        DemoIncidentStatusResponse
    ),
)
def refresh_demo_incidents(
    db: Session = Depends(
        get_db
    ),
):

    demo_ids = (
        current_demo_ids(
            db
        )
    )

    if (
        demo_ids
        != DEMO_IDS
    ):
        raise HTTPException(
            status_code=409,
            detail=(
                "Current demo incidents "
                "have not been generated yet."
            ),
        )

    incidents = db.scalars(
        select(
            Incident
        )
        .where(
            Incident.id.in_(
                DEMO_IDS
            ),
            Incident.is_demo.is_(
                True
            ),
        )
        .order_by(
            Incident.id.asc()
        )
    ).all()

    for incident in incidents:

        detected_at = (
            demo_detected_at(
                incident.id
            )
        )

        incident.detected_at = (
            detected_at
        )

        incident.resolved_at = (
            demo_resolved_at(
                detected_at,
                incident.status,
            )
        )

    db.commit()

    return (
        DemoIncidentStatusResponse(
            ready=True,

            demo_ids=(
                DEMO_IDS
            ),
        )
    )


# ============================================================
# NORMAL LIVE BROWSER INCIDENT
# ============================================================

@router.post(
    "",
    response_model=(
        BrowserIncidentResponse
    ),
)
def create_browser_incident(
    payload: BrowserIncidentCreate,

    db: Session = Depends(
        get_db
    ),
):

    camera = db.get(
        Camera,
        payload.camera_id,
    )

    if camera is None:
        raise HTTPException(
            status_code=400,
            detail=(
                f"Camera "
                f"{payload.camera_id} "
                "does not exist."
            ),
        )

    missing_ppe = (
        normalize_missing_ppe(
            payload.missing_ppe
        )
    )

    incident_payload = (
        IncidentCreate(
            camera_id=(
                payload.camera_id
            ),

            track_id=(
                payload.track_id
            ),

            violation_type=(
                missing_ppe
            ),

            missing_ppe=[
                missing_ppe
            ],

            severity=(
                SEVERITY_BY_PPE[
                    missing_ppe
                ]
            ),

            confidence=(
                payload.confidence
            ),

            evidence_path=None,
        )
    )

    incident, created = (
        create_incident_if_new(
            db,
            incident_payload,
        )
    )

    evidence_saved = False

    if (
        created
        and payload.evidence_image
    ):

        image_bytes, mime_type = (
            decode_evidence_image(
                payload.evidence_image
            )
        )

        db.flush()

        save_evidence_bytes_to_db(
            db=db,

            incident_id=(
                incident.id
            ),

            image_bytes=(
                image_bytes
            ),

            mime_type=(
                mime_type
            ),

            keep_latest=100,
        )

        evidence_saved = True

    db.commit()

    db.refresh(
        incident
    )

    return (
        BrowserIncidentResponse(
            created=(
                created
            ),

            incident=(
                IncidentRead
                .model_validate(
                    incident
                )
            ),

            evidence_saved=(
                evidence_saved
            ),
        )
    )